const planKey='token-field-plan-settings-v1',eventKey='token-field-reset-events-v1';function readData(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}function writeData(k,v){localStorage.setItem(k,JSON.stringify(v))}function escDash(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function beijingToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}function nextDate(start,period){if(period==='once')return '';let d=new Date(start+'T12:00:00Z');if(period==='daily')d.setUTCDate(d.getUTCDate()+1);if(period==='weekly')d.setUTCDate(d.getUTCDate()+7);if(period==='monthly'){let day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+1);let max=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,max))}return d.toISOString().slice(0,10)}const originalRender=render;render=function(){originalRender();renderPlan()};function renderPlan(){const ids=getPlan(),settings=readData(planKey,{}),today=beijingToday(),list=document.querySelector('#plan-list');let entries=ids.map(id=>items.find(x=>x.id===id)).filter(Boolean);document.querySelector('#plan-total').textContent=entries.length;document.querySelector('#plan-due').textContent=entries.filter(x=>!settings[x.id]?.completed&&(!settings[x.id]?.next||settings[x.id].next<=today)).length;document.querySelector('#plan-done').textContent=entries.filter(x=>settings[x.id]?.last===today).length;if(!entries.length){list.innerHTML='<div class="plan-empty">♡<h3>还没有领取计划</h3><p>从福利库挑选感兴趣的项目，加入后可以设置领取周期。</p><a href="#benefits">去福利库看看 →</a></div>';return}list.innerHTML=entries.map(x=>{let st=settings[x.id]||{},period=st.period||'once',date=st.next||'',completed=!!st.completed;return `<article class="plan-row" data-plan="${x.id}"><div class="plan-title"><div class="plan-logo">${icons[x.id]?`<img src="icons/${icons[x.id]}" alt="">`:escDash(x.icon)}</div><div><strong>${escDash(x.name)}</strong><small>${escDash(x.type)} · ${escDash(quotas[x.id])}</small></div></div><div class="plan-config"><label>领取周期<select data-field="period"><option value="once" ${period==='once'?'selected':''}>一次性</option><option value="daily" ${period==='daily'?'selected':''}>每天</option><option value="weekly" ${period==='weekly'?'selected':''}>每周</option><option value="monthly" ${period==='monthly'?'selected':''}>每月</option></select></label><label>下次领取<input data-field="next" type="date" value="${escDash(date)}"></label></div><div class="plan-actions"><span>${completed?'已完成':date&&date>today?'下次 '+escDash(date):'待领取'}</span><a href="${x.url}" target="_blank" rel="noopener noreferrer">前往官方 ↗</a><button data-action="done">${completed?'重新启用':'标记已领'}</button><button data-action="remove" aria-label="移除 ${escDash(x.name)}">移除</button></div></article>`}).join('');list.querySelectorAll('[data-plan]').forEach(row=>{let id=row.dataset.plan;row.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('change',()=>{let v=readData(planKey,{});v[id]={...v[id],[input.dataset.field]:input.value,completed:false};writeData(planKey,v);renderPlan()}));row.querySelector('[data-action=remove]').onclick=()=>{toggle(id)};row.querySelector('[data-action=done]').onclick=()=>{let v=readData(planKey,{}),st=v[id]||{};if(st.completed)st.completed=false;else{st.last=today;if((st.period||'once')==='once')st.completed=true;else{let date=st.next||today;while(date<=today)date=nextDate(date,st.period);st.next=date}}v[id]=st;writeData(planKey,v);renderPlan()}})}renderPlan();
const radarData={codex:{brand:'CODEX / OPENAI',title:'Codex 额度记录',desc:'关注官方对额度重置或重置卡的说明；具体适用账户和到账时间以官方公告与账户为准。',symbol:'✳',link:'https://help.openai.com/en/articles/20001498-how-resets-work-in-codex'},claude:{brand:'CLAUDE / ANTHROPIC',title:'Claude 额度记录',desc:'查看 Claude 账户的使用上限及刷新信息；是否有额外重置请以 Anthropic 公告为准。',symbol:'✦',link:'https://support.claude.com/'},grok:{brand:'GROK BOT / XAI',title:'Grok Bot 额度记录',desc:'关注 Grok Bot 的公开公告；Grok Bot 的使用额度与其他 Grok 产品可能不同。',symbol:'◉',link:'https://help.x.com/en/using-x/about-grok'}};let radarProduct='codex',selectedDay=beijingToday(),month=selectedDay.slice(0,7);const eventForm=document.querySelector('#event-form');function renderRadar(){const data=radarData[radarProduct],events=readData(eventKey,[]);document.querySelector('#radar-brand').textContent=data.brand;document.querySelector('#radar-title').textContent=data.title;document.querySelector('#radar-desc').textContent=data.desc;document.querySelector('#radar-symbol').textContent=data.symbol;document.querySelector('#radar-official').href=data.link;document.querySelectorAll('[data-product]').forEach(b=>b.classList.toggle('active',b.dataset.product===radarProduct));const [y,m]=month.split('-').map(Number),first=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7,count=new Date(Date.UTC(y,m,0)).getUTCDate();document.querySelector('#month-title').textContent=`${y} 年 ${m} 月`;let html='<span></span>'.repeat(first);for(let n=1;n<=count;n++){let day=`${month}-${String(n).padStart(2,'0')}`,has=events.some(e=>e.product===radarProduct&&e.day===day);html+=`<button data-day="${day}" class="${day===selectedDay?'selected ':''}${has?'has-event':''}" aria-label="${day}${has?' 有记录':''}">${n}${has?'<i></i>':''}</button>`}document.querySelector('#calendar-grid').innerHTML=html;document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.day;eventForm.hidden=true;renderRadar()});document.querySelector('#selected-date').textContent=selectedDay;let dayEvents=events.filter(e=>e.product===radarProduct&&e.day===selectedDay);document.querySelector('#event-list').innerHTML=dayEvents.length?dayEvents.map(e=>`<div class="event-entry"><span>${escDash(e.kind)}</span><p>${escDash(e.note)}</p>${e.url?`<a href="${escDash(e.url)}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a>`:''}<button data-delete="${escDash(e.id)}">删除</button></div>`).join(''):'<div class="event-empty"><b>这一天没有记录</b><p>这里仅显示你添加的记录，不代表当天没有发生重置。</p></div>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{writeData(eventKey,readData(eventKey,[]).filter(e=>e.id!==b.dataset.delete));renderRadar()})}document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{radarProduct=b.dataset.product;eventForm.hidden=true;renderRadar()});function shiftMonth(offset){let [y,m]=month.split('-').map(Number),d=new Date(Date.UTC(y,m-1+offset,1));month=d.toISOString().slice(0,7);selectedDay=month+'-01';renderRadar()}document.querySelector('#month-prev').onclick=()=>shiftMonth(-1);document.querySelector('#month-next').onclick=()=>shiftMonth(1);document.querySelector('#add-event').onclick=()=>{eventForm.hidden=false};document.querySelector('#cancel-event').onclick=()=>{eventForm.hidden=true};eventForm.onsubmit=e=>{e.preventDefault();let f=new FormData(eventForm),url=String(f.get('url')||'');if(url&&!/^https?:\/\//i.test(url))return;let a=readData(eventKey,[]);a.push({id:crypto.randomUUID(),product:radarProduct,day:selectedDay,kind:String(f.get('kind')),note:String(f.get('note')).trim(),url});writeData(eventKey,a);eventForm.reset();eventForm.hidden=true;renderRadar()};renderRadar();

let feedSnapshot={products:{}};async function loadResetFeed(){try{const r=await fetch('reset-feed.json',{cache:'no-store'});if(!r.ok)throw new Error('unavailable');feedSnapshot=await r.json();renderFeed()}catch{document.querySelector('#feed-state').textContent='无法读取数据，不能判断最新公告'}}function renderFeed(){const data=feedSnapshot.products?.[radarProduct],state=document.querySelector('#feed-state'),list=document.querySelector('#feed-list');if(!data){state.textContent='尚未连接公告数据';list.innerHTML='';return}let age=Date.now()-Date.parse(data.lastSuccessAt||'');state.textContent=data.state==='ok'&&age<3600000?'上次成功检查：'+new Date(data.lastSuccessAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'（北京时间）':data.state==='error'?'最近采集失败，以下可能过期':'数据可能过期，无法确认最新状态';list.innerHTML=(data.posts||[]).slice(0,8).map(p=>`<div class="feed-entry"><span>待核验 · ${escDash(new Date(p.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</span><p>${escDash(p.text)}</p><a href="${escDash(p.url)}" target="_blank" rel="noopener noreferrer">查看官方原帖 ↗</a></div>`).join('')||'<p>没有已采集的线索；这不代表没有公告。</p>'}document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',renderFeed));loadResetFeed();
